import Foundation

/// What this build speaks. 4 added `movePane`, 5 `listDirectory`, 6 the
/// `den` CLI's control channel.
public let protocolVersion: UInt16 = 6
/// The oldest version dend still serves, and what clients say hello with so
/// an older dend (which wants an exact match) keeps working. Features newer
/// than this are used only when dend's welcome reports a version that has them.
public let minimumProtocolVersion: UInt16 = 3

/// Messages a client sends to dend. IDs for new objects are generated by the
/// client so it can focus what it created without waiting for a reply.
public enum ClientMessage: Equatable, Sendable {
    case hello(version: UInt16, client: String)
    case listSessions
    case createSession(id: SessionID, name: String, size: GridSize)
    /// Streams every session's layout and panes to this client, including
    /// sessions created later. Switching sessions is then purely local.
    case subscribe
    case renameSession(SessionID, name: String)
    case renameTab(TabID, title: String?)
    case moveTab(TabID, index: UInt16)
    case killSession(SessionID)
    case newTab(session: SessionID, tab: TabID, pane: PaneID, size: GridSize, cwd: String?)
    case splitPane(target: PaneID, new: PaneID, axis: SplitAxis, size: GridSize)
    case setSplitRatio(tab: TabID, path: [UInt8], ratio: Float)
    case closePane(PaneID)
    /// Protocol 4: moves a pane within its tab, beside `to` or swapped with it.
    case movePane(PaneID, to: PaneID, placement: PanePlacement)
    case input(PaneID, Data)
    case resize(PaneID, GridSize)
    /// Protocol 5: the entries of a folder on dend's host, so a remote
    /// client can browse it. A leading `~` means the host user's home.
    case listDirectory(request: UInt32, path: String)
    /// Protocol 6: a JSON `ControlRequest`; dend answers with a
    /// `controlReply` carrying the same request number.
    case control(request: UInt32, Data)
}

/// Messages dend sends to clients. Pane output is ordered with resizes so
/// every replica applies the same sequence the server's terminal saw.
public enum ServerMessage: Equatable, Sendable {
    case welcome(version: UInt16, host: String)
    case sessions([SessionSummary])
    case layout(SessionLayout)
    case paneSnapshot(PaneID, Data)
    case paneOutput(PaneID, Data)
    case paneResized(PaneID, GridSize)
    case paneMeta(PaneID, PaneMeta)
    case paneExited(PaneID, status: Int32)
    /// The pane's full set of OSC 7501 records, sent on change and on attach.
    case programStatus(PaneID, [StatusRecord])
    case sessionClosed(SessionID)
    /// Protocol 5: reply to `listDirectory`. `path` is resolved (no `~`);
    /// entries are empty when the folder can't be read.
    case directoryListing(request: UInt32, path: String, entries: [DirectoryEntry])
    /// Protocol 6: a JSON `ControlReply` to `control`.
    case controlReply(request: UInt32, Data)
    /// Protocol 6: a JSON `ControlEvent`, sent after `watchEvents`.
    case controlEvent(Data)
    case error(String)
}

// MARK: - Encoding

extension BinaryWriter {
    mutating func gridSize(_ s: GridSize) {
        u16(s.cols)
        u16(s.rows)
        u32(s.cellWidthPx)
        u32(s.cellHeightPx)
    }

    mutating func node(_ n: SplitNode) {
        switch n {
        case .pane(let id):
            u8(0)
            uuid(id.raw)
        case .split(let axis, let ratio, let a, let b):
            u8(1)
            u8(axis.rawValue)
            f32(ratio)
            node(a)
            node(b)
        }
    }

    mutating func summary(_ s: SessionSummary) {
        uuid(s.id.raw)
        string(s.name)
        u32(s.tabCount)
    }

    /// Phase as a tag; absent kind or progress is 0xFF.
    mutating func statusRecord(_ r: StatusRecord) {
        string(r.id.joined(separator: "/"))
        switch r.phase {
        case .idle: u8(0); u8(0xFF); u8(0xFF)
        case .working(let progress): u8(1); u8(0xFF); u8(progress ?? 0xFF)
        case .done: u8(2); u8(0xFF); u8(0xFF)
        case .blocked(let kind, let progress):
            u8(3); u8(kind.flatMap { BlockedKind.allCases.firstIndex(of: $0) }.map(UInt8.init) ?? 0xFF); u8(progress ?? 0xFF)
        case .error: u8(4); u8(0xFF); u8(0xFF)
        }
        optionalString(r.app)
        optionalString(r.title)
        optionalString(r.msg)
    }
}

extension BinaryReader {
    mutating func gridSize(_ field: String) throws(DecodeError) -> GridSize {
        GridSize(cols: try u16(field), rows: try u16(field), cellWidthPx: try u32(field), cellHeightPx: try u32(field))
    }

    mutating func node(depth: Int = 0) throws(DecodeError) -> SplitNode {
        // Bound recursion so a hostile peer cannot blow the stack.
        guard depth < 64 else { throw .invalidTag(255, type: "SplitNode depth") }
        let tag = try u8("node.tag")
        switch tag {
        case 0:
            return .pane(PaneID(try uuid("node.pane")))
        case 1:
            let rawAxis = try u8("node.axis")
            guard let axis = SplitAxis(rawValue: rawAxis) else { throw .invalidTag(rawAxis, type: "SplitAxis") }
            let ratio = try f32("node.ratio")
            return .split(axis: axis, ratio: ratio, first: try node(depth: depth + 1), second: try node(depth: depth + 1))
        default:
            throw .invalidTag(tag, type: "SplitNode")
        }
    }

    mutating func summary() throws(DecodeError) -> SessionSummary {
        SessionSummary(id: SessionID(try uuid("session.id")), name: try string("session.name"), tabCount: try u32("session.tabCount"))
    }

    mutating func statusRecord() throws(DecodeError) -> StatusRecord {
        let path = try string("status.record.id")
        let tag = try u8("status.record.phase")
        let rawKind = try u8("status.record.kind")
        let rawProgress = try u8("status.record.progress")
        let progress = rawProgress == 0xFF ? nil : rawProgress
        let phase: ProgramPhase
        switch tag {
        case 0: phase = .idle
        case 1: phase = .working(progress: progress)
        case 2: phase = .done
        case 3:
            guard rawKind == 0xFF || Int(rawKind) < BlockedKind.allCases.count else { throw .invalidTag(rawKind, type: "BlockedKind") }
            phase = .blocked(rawKind == 0xFF ? nil : BlockedKind.allCases[Int(rawKind)], progress: progress)
        case 4: phase = .error
        default: throw .invalidTag(tag, type: "ProgramPhase")
        }
        return StatusRecord(
            id: path.isEmpty ? [] : path.split(separator: "/").map(String.init),
            phase: phase,
            app: try optionalString("status.record.app"),
            title: try optionalString("status.record.title"),
            msg: try optionalString("status.record.msg")
        )
    }
}

extension ClientMessage {
    public func encode() -> Data {
        var w = BinaryWriter()
        switch self {
        case .hello(let version, let client):
            w.u8(0x01); w.u16(version); w.string(client)
        case .listSessions:
            w.u8(0x02)
        case .createSession(let id, let name, let size):
            w.u8(0x03); w.uuid(id.raw); w.string(name); w.gridSize(size)
        case .subscribe:
            w.u8(0x04)
        case .renameSession(let id, let name):
            w.u8(0x05); w.uuid(id.raw); w.string(name)
        case .renameTab(let id, let title):
            w.u8(0x0D); w.uuid(id.raw); w.optionalString(title)
        case .moveTab(let id, let index):
            w.u8(0x0E); w.uuid(id.raw); w.u16(index)
        case .killSession(let id):
            w.u8(0x06); w.uuid(id.raw)
        case .newTab(let session, let tab, let pane, let size, let cwd):
            w.u8(0x07); w.uuid(session.raw); w.uuid(tab.raw); w.uuid(pane.raw); w.gridSize(size); w.optionalString(cwd)
        case .splitPane(let target, let new, let axis, let size):
            w.u8(0x08); w.uuid(target.raw); w.uuid(new.raw); w.u8(axis.rawValue); w.gridSize(size)
        case .setSplitRatio(let tab, let path, let ratio):
            w.u8(0x09); w.uuid(tab.raw); w.bytes(Data(path)); w.f32(ratio)
        case .closePane(let id):
            w.u8(0x0A); w.uuid(id.raw)
        case .movePane(let pane, let target, let placement):
            w.u8(0x0F); w.uuid(pane.raw); w.uuid(target.raw); w.u8(placement.rawValue)
        case .input(let id, let bytes):
            w.u8(0x0B); w.uuid(id.raw); w.bytes(bytes)
        case .resize(let id, let size):
            w.u8(0x0C); w.uuid(id.raw); w.gridSize(size)
        case .listDirectory(let request, let path):
            w.u8(0x10); w.u32(request); w.string(path)
        case .control(let request, let json):
            w.u8(0x11); w.u32(request); w.bytes(json)
        }
        return w.data
    }

    public static func decode(_ data: Data) throws(DecodeError) -> ClientMessage {
        var r = BinaryReader(data)
        let tag = try r.u8("client.tag")
        switch tag {
        case 0x01: return .hello(version: try r.u16("hello.version"), client: try r.string("hello.client"))
        case 0x02: return .listSessions
        case 0x03: return .createSession(id: SessionID(try r.uuid("create.id")), name: try r.string("create.name"), size: try r.gridSize("create.size"))
        case 0x04: return .subscribe
        case 0x05: return .renameSession(SessionID(try r.uuid("rename.id")), name: try r.string("rename.name"))
        case 0x0D: return .renameTab(TabID(try r.uuid("renameTab.id")), title: try r.optionalString("renameTab.title"))
        case 0x0E: return .moveTab(TabID(try r.uuid("moveTab.id")), index: try r.u16("moveTab.index"))
        case 0x06: return .killSession(SessionID(try r.uuid("kill.id")))
        case 0x07:
            return .newTab(
                session: SessionID(try r.uuid("newTab.session")),
                tab: TabID(try r.uuid("newTab.tab")),
                pane: PaneID(try r.uuid("newTab.pane")),
                size: try r.gridSize("newTab.size"),
                cwd: try r.optionalString("newTab.cwd")
            )
        case 0x08:
            let target = PaneID(try r.uuid("split.target"))
            let new = PaneID(try r.uuid("split.new"))
            let rawAxis = try r.u8("split.axis")
            guard let axis = SplitAxis(rawValue: rawAxis) else { throw .invalidTag(rawAxis, type: "SplitAxis") }
            return .splitPane(target: target, new: new, axis: axis, size: try r.gridSize("split.size"))
        case 0x09:
            return .setSplitRatio(tab: TabID(try r.uuid("ratio.tab")), path: [UInt8](try r.bytes("ratio.path")), ratio: try r.f32("ratio.value"))
        case 0x0A: return .closePane(PaneID(try r.uuid("close.id")))
        case 0x0F:
            let pane = PaneID(try r.uuid("move.pane"))
            let target = PaneID(try r.uuid("move.target"))
            let raw = try r.u8("move.placement")
            guard let placement = PanePlacement(rawValue: raw) else { throw .invalidTag(raw, type: "PanePlacement") }
            return .movePane(pane, to: target, placement: placement)
        case 0x0B: return .input(PaneID(try r.uuid("input.id")), try r.bytes("input.bytes"))
        case 0x0C: return .resize(PaneID(try r.uuid("resize.id")), try r.gridSize("resize.size"))
        case 0x10: return .listDirectory(request: try r.u32("list.request"), path: try r.string("list.path"))
        case 0x11: return .control(request: try r.u32("control.request"), try r.bytes("control.json"))
        default: throw .invalidTag(tag, type: "ClientMessage")
        }
    }
}

extension ServerMessage {
    public func encode() -> Data {
        var w = BinaryWriter()
        encode(into: &w)
        return w.data
    }

    /// `Frame.wrap(encode())` without the extra copy; the pane output hot
    /// path sends every PTY byte through this.
    public func framed() -> Data {
        let payload = switch self {
        case .paneOutput(_, let bytes), .paneSnapshot(_, let bytes): bytes.count
        default: 0
        }
        var w = BinaryWriter(framedCapacity: payload + 32)
        encode(into: &w)
        return w.finishFrame()
    }

    private func encode(into w: inout BinaryWriter) {
        switch self {
        case .welcome(let version, let host):
            w.u8(0x81); w.u16(version); w.string(host)
        case .sessions(let list):
            w.u8(0x82); w.u32(UInt32(list.count))
            for s in list { w.summary(s) }
        case .layout(let layout):
            w.u8(0x83); w.summary(layout.session); w.u32(UInt32(layout.tabs.count))
            for t in layout.tabs { w.uuid(t.id.raw); w.node(t.root); w.optionalString(t.title) }
        case .paneSnapshot(let id, let bytes):
            w.u8(0x84); w.uuid(id.raw); w.bytes(bytes)
        case .paneOutput(let id, let bytes):
            w.u8(0x85); w.uuid(id.raw); w.bytes(bytes)
        case .paneResized(let id, let size):
            w.u8(0x86); w.uuid(id.raw); w.gridSize(size)
        case .paneMeta(let id, let meta):
            w.u8(0x87); w.uuid(id.raw); w.string(meta.process); w.optionalString(meta.cwd)
        case .paneExited(let id, let status):
            w.u8(0x88); w.uuid(id.raw); w.i32(status)
        case .sessionClosed(let id):
            w.u8(0x89); w.uuid(id.raw)
        case .programStatus(let id, let records):
            w.u8(0x8A); w.uuid(id.raw); w.u32(UInt32(records.count))
            for record in records { w.statusRecord(record) }
        case .directoryListing(let request, let path, let entries):
            w.u8(0x8B); w.u32(request); w.string(path); w.u32(UInt32(entries.count))
            for entry in entries { w.string(entry.name); w.u8(entry.isDirectory ? 1 : 0) }
        case .controlReply(let request, let json):
            w.u8(0x8C); w.u32(request); w.bytes(json)
        case .controlEvent(let json):
            w.u8(0x8D); w.bytes(json)
        case .error(let message):
            w.u8(0x8F); w.string(message)
        }
    }

    public static func decode(_ data: Data) throws(DecodeError) -> ServerMessage {
        var r = BinaryReader(data)
        let tag = try r.u8("server.tag")
        switch tag {
        case 0x81: return .welcome(version: try r.u16("welcome.version"), host: try r.string("welcome.host"))
        case 0x82:
            let count = try r.u32("sessions.count")
            var list: [SessionSummary] = []
            for _ in 0 ..< count { list.append(try r.summary()) }
            return .sessions(list)
        case 0x83:
            let session = try r.summary()
            let count = try r.u32("layout.tabCount")
            var tabs: [TabLayout] = []
            for _ in 0 ..< count {
                tabs.append(TabLayout(id: TabID(try r.uuid("layout.tab")), root: try r.node(), title: try r.optionalString("layout.title")))
            }
            return .layout(SessionLayout(session: session, tabs: tabs))
        case 0x84: return .paneSnapshot(PaneID(try r.uuid("snapshot.id")), try r.bytes("snapshot.bytes"))
        case 0x85: return .paneOutput(PaneID(try r.uuid("output.id")), try r.bytes("output.bytes"))
        case 0x86: return .paneResized(PaneID(try r.uuid("resized.id")), try r.gridSize("resized.size"))
        case 0x87:
            return .paneMeta(PaneID(try r.uuid("meta.id")), PaneMeta(process: try r.string("meta.process"), cwd: try r.optionalString("meta.cwd")))
        case 0x88: return .paneExited(PaneID(try r.uuid("exited.id")), status: try r.i32("exited.status"))
        case 0x89: return .sessionClosed(SessionID(try r.uuid("sessionClosed.id")))
        case 0x8A:
            let id = PaneID(try r.uuid("status.id"))
            let count = try r.u32("status.count")
            guard count <= UInt32(StatusRecords.capacity) else { throw .invalidTag(255, type: "programStatus count") }
            var records: [StatusRecord] = []
            for _ in 0 ..< count { records.append(try r.statusRecord()) }
            return .programStatus(id, records)
        case 0x8B:
            let request = try r.u32("listing.request")
            let path = try r.string("listing.path")
            let count = try r.u32("listing.count")
            guard count <= DirectoryEntry.maxPerListing else { throw .invalidTag(255, type: "directoryListing count") }
            var entries: [DirectoryEntry] = []
            for _ in 0 ..< count { entries.append(DirectoryEntry(name: try r.string("listing.name"), isDirectory: try r.u8("listing.kind") == 1)) }
            return .directoryListing(request: request, path: path, entries: entries)
        case 0x8C: return .controlReply(request: try r.u32("controlReply.request"), try r.bytes("controlReply.json"))
        case 0x8D: return .controlEvent(try r.bytes("controlEvent.json"))
        case 0x8F: return .error(try r.string("error.message"))
        default: throw .invalidTag(tag, type: "ServerMessage")
        }
    }
}
